-- Kestrel, the sample company, as a local install's kestrel-db serves it.
-- Written by scripts/sample-company.mjs; edit that, not this.

CREATE TABLE accounts (
  account_id text NOT NULL,
  name text,
  industry text,
  country text,
  city text,
  employees integer,
  segment text,
  account_manager text,
  customer_since date,
  PRIMARY KEY (account_id)
);

CREATE TABLE contacts (
  contact_id text NOT NULL,
  account_id text,
  full_name text,
  title text,
  email text,
  role text,
  PRIMARY KEY (contact_id),
  FOREIGN KEY (account_id) REFERENCES accounts (account_id)
);

CREATE TABLE subscriptions (
  subscription_id text NOT NULL,
  account_id text,
  plan text,
  seats integer,
  price_per_seat_usd numeric(10,2),
  discount_pct integer,
  monthly_amount_usd numeric(12,2),
  billing text,
  status text,
  started_on date,
  term_months integer,
  current_term_end date,
  ended_on date,
  cancel_reason text,
  PRIMARY KEY (subscription_id),
  FOREIGN KEY (account_id) REFERENCES accounts (account_id)
);

CREATE TABLE invoices (
  invoice_id text NOT NULL,
  subscription_id text,
  account_id text,
  issued_on date,
  due_on date,
  amount_usd numeric(12,2),
  status text,
  paid_on date,
  PRIMARY KEY (invoice_id),
  FOREIGN KEY (subscription_id) REFERENCES subscriptions (subscription_id),
  FOREIGN KEY (account_id) REFERENCES accounts (account_id)
);

CREATE TABLE support_tickets (
  ticket_id text NOT NULL,
  account_id text,
  requester_id text,
  opened_at timestamptz,
  closed_at timestamptz,
  priority text,
  status text,
  category text,
  subject text,
  PRIMARY KEY (ticket_id),
  FOREIGN KEY (account_id) REFERENCES accounts (account_id),
  FOREIGN KEY (requester_id) REFERENCES contacts (contact_id)
);

CREATE TABLE product_usage (
  account_id text NOT NULL,
  month text NOT NULL,
  active_users integer,
  jobs_scheduled integer,
  PRIMARY KEY (account_id, month),
  FOREIGN KEY (account_id) REFERENCES accounts (account_id)
);

CREATE ROLE kestrel_reader LOGIN PASSWORD 'kestrel';
GRANT USAGE ON SCHEMA public TO kestrel_reader;
GRANT SELECT ON ALL TABLES IN SCHEMA public TO kestrel_reader;
